import{_ as e,o,c as a,O as l}from"./chunks/framework.db831a78.js";const T=JSON.parse('{"title":"HTTP","description":"","frontmatter":{},"headers":[],"relativePath":"interview/浏览器/http.md","filePath":"interview/浏览器/http.md","lastUpdated":1788941422000}'),i={name:"interview/浏览器/http.md"};function n(r,t,s,d,c,h){return o(),a("div",null,t[0]||(t[0]=[l(`<h1 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h1><blockquote><p>HTTP 是浏览器面试的核心地带：报文、方法、状态码、头部、缓存、跨域、连接管理、HTTP/2/3、HTTPS 一网打尽。本文聚焦 HTTP 层，TCP/TLS 传输层细节见<a href="./../后端/Java/07-计算机网络">计算机网络笔记</a>，缓存与跨域的完整展开见<a href="./浏览器缓存">浏览器缓存</a>与<a href="./跨域">跨域</a>。</p></blockquote><h2 id="http-报文结构" tabindex="-1">HTTP 报文结构 <a class="header-anchor" href="#http-报文结构" aria-label="Permalink to &quot;HTTP 报文结构&quot;">​</a></h2><h3 id="http-报文由哪几部分组成" tabindex="-1">HTTP 报文由哪几部分组成 <a class="header-anchor" href="#http-报文由哪几部分组成" aria-label="Permalink to &quot;HTTP 报文由哪几部分组成&quot;">​</a></h3><ul><li>HTTP 报文分两类：<strong>请求报文</strong>与<strong>响应报文</strong>，结构都是三部分：<strong>start line（起始行）+ header（首部）+ body（主体）</strong>。</li><li>起始行与首部之间、首部与主体之间用空行（<code>\\r\\n\\r\\n</code>）分隔；首部是 <code>键: 值</code> 的多行文本。</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">请求报文：</span></span>
<span class="line"><span style="color:#e1e4e8;">POST /api/login HTTP/1.1        ← 请求行：方法 + 路径 + 版本</span></span>
<span class="line"><span style="color:#e1e4e8;">Host: www.example.com</span></span>
<span class="line"><span style="color:#e1e4e8;">Content-Type: application/json</span></span>
<span class="line"><span style="color:#e1e4e8;">Content-Length: 32</span></span>
<span class="line"><span style="color:#e1e4e8;"></span></span>
<span class="line"><span style="color:#e1e4e8;">{&quot;username&quot;:&quot;tom&quot;}              ← 请求体（可空）</span></span>
<span class="line"><span style="color:#e1e4e8;"></span></span>
<span class="line"><span style="color:#e1e4e8;">响应报文：</span></span>
<span class="line"><span style="color:#e1e4e8;">HTTP/1.1 200 OK                 ← 状态行：版本 + 状态码 + 原因短语</span></span>
<span class="line"><span style="color:#e1e4e8;">Content-Type: application/json</span></span>
<span class="line"><span style="color:#e1e4e8;">Content-Length: 15</span></span>
<span class="line"><span style="color:#e1e4e8;"></span></span>
<span class="line"><span style="color:#e1e4e8;">{&quot;code&quot;: 0}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">请求报文：</span></span>
<span class="line"><span style="color:#24292e;">POST /api/login HTTP/1.1        ← 请求行：方法 + 路径 + 版本</span></span>
<span class="line"><span style="color:#24292e;">Host: www.example.com</span></span>
<span class="line"><span style="color:#24292e;">Content-Type: application/json</span></span>
<span class="line"><span style="color:#24292e;">Content-Length: 32</span></span>
<span class="line"><span style="color:#24292e;"></span></span>
<span class="line"><span style="color:#24292e;">{&quot;username&quot;:&quot;tom&quot;}              ← 请求体（可空）</span></span>
<span class="line"><span style="color:#24292e;"></span></span>
<span class="line"><span style="color:#24292e;">响应报文：</span></span>
<span class="line"><span style="color:#24292e;">HTTP/1.1 200 OK                 ← 状态行：版本 + 状态码 + 原因短语</span></span>
<span class="line"><span style="color:#24292e;">Content-Type: application/json</span></span>
<span class="line"><span style="color:#24292e;">Content-Length: 15</span></span>
<span class="line"><span style="color:#24292e;"></span></span>
<span class="line"><span style="color:#24292e;">{&quot;code&quot;: 0}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="请求行与状态行分别怎么写" tabindex="-1">请求行与状态行分别怎么写 <a class="header-anchor" href="#请求行与状态行分别怎么写" aria-label="Permalink to &quot;请求行与状态行分别怎么写&quot;">​</a></h3><ul><li><strong>请求行</strong>：<code>方法 空格 请求目标 空格 HTTP版本</code>。请求目标通常是路径 + 查询串（<code>/path?a=1</code>），也有绝对 URI（代理场景）与 <code>*</code>（OPTIONS 通配）。</li><li><strong>状态行</strong>：<code>HTTP版本 空格 状态码 空格 原因短语</code>。原因短语是给人看的，机器只认状态码。</li><li>面试常考：状态行第一个数字表示响应类别（1xx~5xx），如 <code>HTTP/1.1 404 Not Found</code>。</li></ul><h3 id="header-与-body-的注意点" tabindex="-1">Header 与 Body 的注意点 <a class="header-anchor" href="#header-与-body-的注意点" aria-label="Permalink to &quot;Header 与 Body 的注意点&quot;">​</a></h3><ul><li>Header 每行一个字段，字段名大小写不敏感；同一字段可多行出现（如多个 <code>Set-Cookie</code>）。</li><li><strong>请求体与响应体都可能为空</strong>：GET 一般无 body；204 响应不允许带 body。</li><li>Header 体积有软限制（服务器/网关通常限 8KB~64KB），超限会 431；Body 大小由 <code>Content-Length</code> 或分块传输给出。</li><li>常见坑：前端用 <code>XMLHttpRequest</code>/<code>fetch</code> 自定义头会触发 CORS 预检（见跨域节）；<code>Content-Length</code> 与实际 body 不符会被服务端判为错误请求。</li></ul><h2 id="http-请求方法" tabindex="-1">HTTP 请求方法 <a class="header-anchor" href="#http-请求方法" aria-label="Permalink to &quot;HTTP 请求方法&quot;">​</a></h2><h3 id="get-和-post-有什么区别" tabindex="-1">GET 和 POST 有什么区别 <a class="header-anchor" href="#get-和-post-有什么区别" aria-label="Permalink to &quot;GET 和 POST 有什么区别&quot;">​</a></h3><ul><li><strong>语义</strong>：GET 表示「获取资源」（安全、只读）；POST 表示「向服务器提交数据、创建/触发处理」。</li><li><strong>幂等</strong>：GET 幂等（重复请求结果一致）；POST 不保证幂等（重复提交可能创建多条订单）。</li><li><strong>位置</strong>：GET 参数一般放 URL query，会被浏览器历史、日志、Referer 泄漏；POST 参数放 body，相对更隐蔽但<strong>不是加密</strong>（HTTPS 才加密）。</li><li><strong>缓存</strong>：GET 默认可被缓存（强缓存/协商缓存）；POST 一般不可缓存（除非显式带 freshness 信息）。</li><li><strong>长度</strong>：URL 长度受浏览器/服务器限制（通常 2KB~8KB）；POST body 容量大得多。</li><li>面试加分：语义化角度 &quot;GET 用于查询，POST 用于变更&quot;，而不是&quot;POST 更安全&quot;。</li></ul><h3 id="什么是幂等-哪些方法幂等" tabindex="-1">什么是幂等，哪些方法幂等 <a class="header-anchor" href="#什么是幂等-哪些方法幂等" aria-label="Permalink to &quot;什么是幂等，哪些方法幂等&quot;">​</a></h3><ul><li><strong>幂等（idempotent）</strong>：同一请求执行一次与执行多次，对服务器资源产生的效果相同（读到的响应可不同，如第二次 404）。</li><li>幂等方法：<code>GET</code>、<code>PUT</code>、<code>DELETE</code>、<code>HEAD</code>、<code>OPTIONS</code>、<code>TRACE</code>。</li><li>非幂等：<code>POST</code>、<code>PATCH</code>（按定义 PATCH 不保证幂等，但实现上可做到）。</li><li>追问点：DELETE 第一次返回 200、第二次返回 404，为什么仍幂等？——因为资源最终状态一致（都是不存在）。</li></ul><h3 id="put-和-post、patch-怎么区分" tabindex="-1">PUT 和 POST、PATCH 怎么区分 <a class="header-anchor" href="#put-和-post、patch-怎么区分" aria-label="Permalink to &quot;PUT 和 POST、PATCH 怎么区分&quot;">​</a></h3><table><thead><tr><th>方法</th><th>语义</th><th>幂等</th><th>典型场景</th></tr></thead><tbody><tr><td>POST</td><td>提交/创建，交给服务器决定位置</td><td>否</td><td>新建订单、登录、上传</td></tr><tr><td>PUT</td><td>用请求体<strong>整体替换</strong>目标资源，URL 由客户端指定</td><td>是</td><td>更新 id=1 的用户（全量）</td></tr><tr><td>PATCH</td><td>对资源做<strong>部分修改</strong></td><td>不保证</td><td>只改用户昵称字段</td></tr></tbody></table><ul><li>面试口径：PUT 是&quot;把资源放成这个样子&quot;（全量、幂等）；PATCH 是&quot;对资源做增量修补&quot;；POST 是&quot;提交处理&quot;。</li></ul><h3 id="head-和-options-的用途" tabindex="-1">HEAD 和 OPTIONS 的用途 <a class="header-anchor" href="#head-和-options-的用途" aria-label="Permalink to &quot;HEAD 和 OPTIONS 的用途&quot;">​</a></h3><ul><li><strong>HEAD</strong>：与 GET 相同但响应<strong>不带 body</strong>，用于只取元信息（检查资源是否存在、看 Content-Length、探活）。</li><li><strong>OPTIONS</strong>：询问服务器支持的能力（响应 <code>Allow: GET, POST...</code>）；同时也是 <strong>CORS 预检请求</strong>使用的方法（见跨域节）。</li><li>应用：下载前先 HEAD 拿到文件大小做断点续传校验；接口文档自动生成常发 OPTIONS 探测。</li></ul><h3 id="什么是-restful-风格" tabindex="-1">什么是 RESTful 风格 <a class="header-anchor" href="#什么是-restful-风格" aria-label="Permalink to &quot;什么是 RESTful 风格&quot;">​</a></h3><ul><li>RESTful 是用 HTTP 语义组织接口的架构风格：<strong>资源用名词 URL 表达，操作用 HTTP 方法表达</strong>。</li><li>口诀：URL 里只有名词、没有动词；动词交给方法。</li></ul><table><thead><tr><th>操作</th><th>非 REST（反例）</th><th>RESTful（正例）</th></tr></thead><tbody><tr><td>查用户</td><td>GET /getUser?id=1</td><td>GET /users/1</td></tr><tr><td>新建用户</td><td>POST /createUser</td><td>POST /users</td></tr><tr><td>改用户</td><td>POST /updateUser</td><td>PUT /users/1（全量）/ PATCH /users/1（部分）</td></tr><tr><td>删用户</td><td>GET /deleteUser?id=1</td><td>DELETE /users/1</td></tr></tbody></table><ul><li>补充要点：状态码表达结果（201 创建成功、204 删除成功、409 冲突）；用查询参数过滤排序（<code>GET /users?role=admin&amp;page=2</code>）；版本化 <code>/v1/users</code>。</li></ul><h2 id="http-状态码" tabindex="-1">HTTP 状态码 <a class="header-anchor" href="#http-状态码" aria-label="Permalink to &quot;HTTP 状态码&quot;">​</a></h2><h3 id="状态码分几类" tabindex="-1">状态码分几类 <a class="header-anchor" href="#状态码分几类" aria-label="Permalink to &quot;状态码分几类&quot;">​</a></h3><table><thead><tr><th>类别</th><th>含义</th><th>代表</th></tr></thead><tbody><tr><td>1xx</td><td>信息性响应</td><td>100 Continue、101 Switching Protocols</td></tr><tr><td>2xx</td><td>成功</td><td>200、201、204、206</td></tr><tr><td>3xx</td><td>重定向</td><td>301、302、304、307、308</td></tr><tr><td>4xx</td><td>客户端错误</td><td>400、401、403、404、405、429</td></tr><tr><td>5xx</td><td>服务端错误</td><td>500、502、503、504</td></tr></tbody></table><h3 id="_2xx-常见状态码" tabindex="-1">2xx 常见状态码 <a class="header-anchor" href="#_2xx-常见状态码" aria-label="Permalink to &quot;2xx 常见状态码&quot;">​</a></h3><ul><li><strong>200 OK</strong>：请求成功，body 为结果。</li><li><strong>201 Created</strong>：创建成功，Location 头指向新资源（POST/PUT 后常见）。</li><li><strong>202 Accepted</strong>：已受理但异步处理中（消息队列、异步任务常用）。</li><li><strong>204 No Content</strong>：成功但无 body（DELETE 成功、PUT 局部更新）。</li><li><strong>206 Partial Content</strong>：范围请求成功（断点续传/视频拖动，配合 Range，见串讲 Q7）。</li></ul><h3 id="_3xx-重定向-301-302-307-308-的区别" tabindex="-1">3xx 重定向：301/302/307/308 的区别 <a class="header-anchor" href="#_3xx-重定向-301-302-307-308-的区别" aria-label="Permalink to &quot;3xx 重定向：301/302/307/308 的区别&quot;">​</a></h3><ul><li><strong>301 Moved Permanently</strong>：永久重定向。方法默认从 POST 改成 GET（历史上 GET 化），新地址用 Location 头给出，搜索引擎会更新收录。</li><li><strong>302 Found</strong>：临时重定向。默认同样 GET 化；语义上&quot;这次先去别处，下次还来问我&quot;。</li><li><strong>303 See Other</strong>：明确&quot;请用 GET 去 Location 取结果&quot;（POST 提交后跳结果页的标准做法）。</li><li><strong>307 Temporary Redirect</strong>：临时重定向，<strong>保持原方法与原 body</strong>（POST 还是 POST）。</li><li><strong>308 Permanent Redirect</strong>：永久重定向，保持方法（307 的永久版）。</li><li>面试常问：301 和 302 默认会把 POST 变 GET（老规范浏览器行为）；要保证方法不变必须用 307/308；https→http 跳转、域名换新用 301。</li></ul><h3 id="_304-是什么、怎么产生" tabindex="-1">304 是什么、怎么产生 <a class="header-anchor" href="#_304-是什么、怎么产生" aria-label="Permalink to &quot;304 是什么、怎么产生&quot;">​</a></h3><ul><li><strong>304 Not Modified</strong>：协商缓存命中的响应——客户端带了 <code>If-None-Match</code>/<code>If-Modified-Since</code>，服务器判断资源没变，返回 304 且<strong>不带 body</strong>，浏览器用本地缓存。</li><li>与重定向不同：304 不跳转，只是&quot;告诉浏览器继续用缓存&quot;。</li><li>完整机制（Last-Modified/ETag 对比、优先级）见<a href="./浏览器缓存">浏览器缓存</a>的协商缓存一节。</li></ul><h3 id="_4xx-客户端错误" tabindex="-1">4xx 客户端错误 <a class="header-anchor" href="#_4xx-客户端错误" aria-label="Permalink to &quot;4xx 客户端错误&quot;">​</a></h3><ul><li><strong>400 Bad Request</strong>：请求语法/参数不对（缺字段、JSON 解析失败）。</li><li><strong>401 Unauthorized</strong>：未认证/凭证失效，响应带 <code>WWW-Authenticate</code> 提示如何认证；与 403 的区别是&quot;你还没证明你是谁&quot;。</li><li><strong>403 Forbidden</strong>：已认证但<strong>无权限</strong>（或服务器拒绝透露存在性）；与 404 常被安全设计故意互换。</li><li><strong>404 Not Found</strong>：资源不存在（或不想暴露存在）。</li><li><strong>405 Method Not Allowed</strong>：方法不支持（如只允许 GET 的接口收到 POST），响应应带 <code>Allow</code> 头。</li><li><strong>429 Too Many Requests</strong>：触发限流，配合 <code>Retry-After</code> 头告知何时重试。</li><li>其他备查：408 请求超时、409 冲突（资源状态冲突）、413 请求体过大、415 媒体类型不支持、431 头过大。</li></ul><h3 id="_5xx-服务端错误-502-与-504-怎么区分" tabindex="-1">5xx 服务端错误：502 与 504 怎么区分 <a class="header-anchor" href="#_5xx-服务端错误-502-与-504-怎么区分" aria-label="Permalink to &quot;5xx 服务端错误：502 与 504 怎么区分&quot;">​</a></h3><ul><li><strong>500 Internal Server Error</strong>：服务器内部异常（代码抛错、没接住）。</li><li><strong>501 Not Implemented</strong>：方法未实现。</li><li><strong>502 Bad Gateway</strong>：网关/代理收到上游的<strong>无效响应</strong>（上游挂了、连不上、返回乱数据）。</li><li><strong>503 Service Unavailable</strong>：服务器过载/维护中，配合 <code>Retry-After</code>。</li><li><strong>504 Gateway Timeout</strong>：网关<strong>等上游响应超时</strong>（代理在规定时间内没等到上游回包）。</li><li>记忆：502 = 上游&quot;回的东西不对/没连上&quot;；504 = 上游&quot;回得太慢超时&quot;；503 = 我自己的服务暂时不可用。</li></ul><h2 id="http-请求头与响应头" tabindex="-1">HTTP 请求头与响应头 <a class="header-anchor" href="#http-请求头与响应头" aria-label="Permalink to &quot;HTTP 请求头与响应头&quot;">​</a></h2><h3 id="content-type-与-accept-内容协商" tabindex="-1">Content-Type 与 Accept（内容协商） <a class="header-anchor" href="#content-type-与-accept-内容协商" aria-label="Permalink to &quot;Content-Type 与 Accept（内容协商）&quot;">​</a></h3><ul><li><strong>Accept</strong>（请求头）：客户端能接受的媒体类型与优先级，如 <code>Accept: text/html,application/json;q=0.9,*/*;q=0.8</code>。</li><li><strong>Content-Type</strong>（实体头，请求/响应都有）：body 的实际类型，如 <code>application/json</code>、<code>text/html; charset=utf-8</code>、<code>application/x-www-form-urlencoded</code>、<code>multipart/form-data; boundary=...</code>（文件上传）。</li><li>配套：<code>Accept-Encoding: gzip, br</code> → 服务器压缩后响应带 <code>Content-Encoding: gzip</code>；<code>Accept-Language</code> → <code>Content-Language</code>。</li><li>前端坑：POST JSON 忘记设 <code>Content-Type: application/json</code>，body 会被按表单解析；<code>form-data</code> 与 <code>urlencoded</code> 结构不同，后端取参方式也不同。</li></ul><h3 id="authorization-认证头" tabindex="-1">Authorization 认证头 <a class="header-anchor" href="#authorization-认证头" aria-label="Permalink to &quot;Authorization 认证头&quot;">​</a></h3><ul><li>请求头 <code>Authorization: Bearer &lt;token&gt;</code>（JWT 常见）或 <code>Authorization: Basic base64(user:pass)</code>。</li><li>服务器对未认证请求返回 <strong>401 + <code>WWW-Authenticate</code></strong>，提示认证方式。</li><li>与 Cookie 的区别：Cookie 由浏览器自动携带，Authorization 由业务代码显式携带（适合前后端分离、跨域）。</li></ul><h3 id="cookie-与-set-cookie-头" tabindex="-1">Cookie 与 Set-Cookie 头 <a class="header-anchor" href="#cookie-与-set-cookie-头" aria-label="Permalink to &quot;Cookie 与 Set-Cookie 头&quot;">​</a></h3><ul><li>响应头 <code>Set-Cookie: name=value; Path=/; HttpOnly; SameSite=Lax; Max-Age=3600</code> 由服务器下发，浏览器存储后，后续同域请求自动带上请求头 <code>Cookie: name=value</code>。</li><li>请求头 <code>Cookie</code> 只是键值对串，不含属性；属性只在 Set-Cookie 时声明。</li><li>安全属性（HttpOnly/Secure/SameSite）的作用与细节见<a href="./浏览器缓存">浏览器缓存</a>与<a href="./前端安全">前端安全</a>。</li></ul><h3 id="cors-相关头有哪些" tabindex="-1">CORS 相关头有哪些 <a class="header-anchor" href="#cors-相关头有哪些" aria-label="Permalink to &quot;CORS 相关头有哪些&quot;">​</a></h3><table><thead><tr><th>头</th><th>方向</th><th>作用</th></tr></thead><tbody><tr><td>Origin</td><td>请求</td><td>声明来源（协议+域名+端口）</td></tr><tr><td>Access-Control-Allow-Origin</td><td>响应</td><td>允许的源（<code>*</code> 或具体源）</td></tr><tr><td>Access-Control-Allow-Methods</td><td>响应</td><td>允许的方法（预检应答）</td></tr><tr><td>Access-Control-Allow-Headers</td><td>响应</td><td>允许的自定义头（预检应答）</td></tr><tr><td>Access-Control-Expose-Headers</td><td>响应</td><td>允许 JS 读取的响应头白名单</td></tr><tr><td>Access-Control-Allow-Credentials</td><td>响应</td><td>是否允许携带凭证（Cookie）</td></tr><tr><td>Access-Control-Max-Age</td><td>响应</td><td>预检结果可缓存秒数</td></tr></tbody></table><h3 id="cache-control-指令速查" tabindex="-1">Cache-Control 指令速查 <a class="header-anchor" href="#cache-control-指令速查" aria-label="Permalink to &quot;Cache-Control 指令速查&quot;">​</a></h3><ul><li>响应指令：<code>public/private</code>（谁能缓存）、<code>max-age=秒</code>（强缓存时长）、<code>no-cache</code>（可用但每次要回源校验=协商）、<code>no-store</code>（禁止一切缓存）、<code>s-maxage</code>（CDN/共享缓存专用）、<code>must-revalidate</code>（过期必须回源）。</li><li>请求指令：<code>no-cache</code>（强制回源校验）、<code>no-store</code>、<code>max-age=0</code>（立即过期重新请求）、<code>only-if-cached</code>。</li><li>与 <code>Expires</code>（HTTP/1.0，绝对时间，客户端时间不可信）的优先级：<code>Cache-Control</code> 优先。</li><li>详细机制与刷新行为（F5/Ctrl+F5）见<a href="./浏览器缓存">浏览器缓存</a>。</li></ul><h3 id="其他高频头一览" tabindex="-1">其他高频头一览 <a class="header-anchor" href="#其他高频头一览" aria-label="Permalink to &quot;其他高频头一览&quot;">​</a></h3><ul><li><code>Host</code>：目标主机+端口，HTTP/1.1 起<strong>必填</strong>（一台服务器挂多个域名靠它区分虚拟主机）。</li><li><code>User-Agent</code>：客户端标识（浏览器/系统版本）。</li><li><code>Referer</code>：来源页面（防盗链、统计）；<code>Origin</code> 是 CORS 用的&quot;来源&quot;（不含路径）。</li><li><code>Connection</code>：<code>keep-alive</code> / <code>close</code>（HTTP/1.1 默认 keep-alive）。</li><li><code>Upgrade</code> + 101：协议升级（WebSocket 握手用）。</li><li><code>X-Forwarded-For</code> / <code>X-Real-IP</code>：代理转发后携带的真实客户端 IP（需信任代理才可信）。</li><li><code>Range</code> / <code>Content-Range</code>：范围请求（断点续传，见串讲 Q7）。</li><li><code>Retry-After</code>：429/503 时告知何时可重试。</li></ul><h2 id="cookie-与-session" tabindex="-1">Cookie 与 Session <a class="header-anchor" href="#cookie-与-session" aria-label="Permalink to &quot;Cookie 与 Session&quot;">​</a></h2><h3 id="为什么需要-cookie-http-无状态问题" tabindex="-1">为什么需要 Cookie（HTTP 无状态问题） <a class="header-anchor" href="#为什么需要-cookie-http-无状态问题" aria-label="Permalink to &quot;为什么需要 Cookie（HTTP 无状态问题）&quot;">​</a></h3><ul><li>HTTP 是无状态协议：服务器不记得上一个请求是谁发的，每个请求相互独立。</li><li>电商购物车、登录态都需要&quot;认出你&quot;，于是用 Cookie 在客户端保存身份标识，每次请求自动捎带，让服务器&quot;有状态&quot;。</li></ul><h3 id="cookie-的关键属性与安全" tabindex="-1">Cookie 的关键属性与安全 <a class="header-anchor" href="#cookie-的关键属性与安全" aria-label="Permalink to &quot;Cookie 的关键属性与安全&quot;">​</a></h3><table><thead><tr><th>属性</th><th>作用</th></tr></thead><tbody><tr><td><code>Domain</code> / <code>Path</code></td><td>限定 cookie 在哪些域/路径下携带</td></tr><tr><td><code>Expires</code> / <code>Max-Age</code></td><td>过期时间（Max-Age 优先级更高）</td></tr><tr><td><code>HttpOnly</code></td><td>JS 无法读取，防 XSS 窃取</td></tr><tr><td><code>Secure</code></td><td>仅 HTTPS 下传输</td></tr><tr><td><code>SameSite=Strict/Lax/None</code></td><td>限制跨站携带，防 CSRF（Lax 是浏览器默认）</td></tr></tbody></table><ul><li>Cookie 单条上限约 4KB、总量有限；会随每次请求自动带上，增大流量，不适合存大对象（见<a href="./浏览器缓存">浏览器缓存</a>的存储对比）。</li></ul><h3 id="session-机制与-sessionid" tabindex="-1">Session 机制与 SessionID <a class="header-anchor" href="#session-机制与-sessionid" aria-label="Permalink to &quot;Session 机制与 SessionID&quot;">​</a></h3><ul><li><strong>Session 是服务端的状态</strong>：用户登录后，服务器建一条 session 记录并生成唯一 <code>SessionID</code>。</li><li>SessionID 通过 <code>Set-Cookie</code>（常见名 <code>JSESSIONID</code>）下发给浏览器，之后每次请求带上，服务器凭它找到对应 session。</li><li>集群部署问题：session 默认存在单机内存，多机需要 session 共享（粘性会话、Redis 集中存储、或换无状态 Token）。</li></ul><h3 id="cookie-与-session-的对比" tabindex="-1">Cookie 与 Session 的对比 <a class="header-anchor" href="#cookie-与-session-的对比" aria-label="Permalink to &quot;Cookie 与 Session 的对比&quot;">​</a></h3><table><thead><tr><th>维度</th><th>Cookie</th><th>Session</th></tr></thead><tbody><tr><td>存储位置</td><td>客户端</td><td>服务端</td></tr><tr><td>容量</td><td>约 4KB</td><td>取决于服务端实现（Redis/内存）</td></tr><tr><td>安全性</td><td>明文存客户端，可被篡改/窃取</td><td>相对安全，但 SessionID 被偷同样危险</td></tr><tr><td>性能</td><td>请求自动携带，占带宽</td><td>每次查 session 有服务端开销</td></tr><tr><td>典型</td><td>记住偏好、跟踪标识</td><td>登录态、购物车</td></tr></tbody></table><ul><li>引申：如果只放&quot;用户 ID&quot;这类明文，<strong>不要在 Cookie 里直接信</strong>，要防篡改（签名/只存 SessionID）。</li></ul><h3 id="token-jwt-与-session-的区别" tabindex="-1">Token / JWT 与 Session 的区别 <a class="header-anchor" href="#token-jwt-与-session-的区别" aria-label="Permalink to &quot;Token / JWT 与 Session 的区别&quot;">​</a></h3><ul><li>JWT 是无状态的：签名信息（含过期时间、用户标识）放在 token 里，服务器验签即可，不查库/不存 session，天然适合分布式与跨域。</li><li>缺点：签发后难以主动失效（黑名单/短有效期+refresh token 补救）；token 体积大。</li><li>面试结论：单体传统项目用 Session+Cookie 简单可靠；前后端分离/微服务/移动端多用 Token(JWT)。</li></ul><h2 id="缓存机制" tabindex="-1">缓存机制 <a class="header-anchor" href="#缓存机制" aria-label="Permalink to &quot;缓存机制&quot;">​</a></h2><h3 id="强缓存与协商缓存一句话区分" tabindex="-1">强缓存与协商缓存一句话区分 <a class="header-anchor" href="#强缓存与协商缓存一句话区分" aria-label="Permalink to &quot;强缓存与协商缓存一句话区分&quot;">​</a></h3><ul><li><strong>强缓存</strong>：命中直接用本地缓存，<strong>不发请求</strong>（<code>200 from memory/disk cache</code>）。</li><li><strong>协商缓存</strong>：<strong>发请求问服务器</strong>，服务器说没变 → 304，浏览器用本地缓存；变了 → 200 + 新资源。</li><li>两者可共存，<strong>强缓存优先</strong>；强缓存没命中/过期才走协商。</li><li>完整原理（Expires/Cache-Control/Last-Modified/ETag、刷新操作影响）见<a href="./浏览器缓存">浏览器缓存</a>，本文不重复展开。</li></ul><h3 id="缓存相关头清单" tabindex="-1">缓存相关头清单 <a class="header-anchor" href="#缓存相关头清单" aria-label="Permalink to &quot;缓存相关头清单&quot;">​</a></h3><table><thead><tr><th>类别</th><th>请求头</th><th>响应头</th></tr></thead><tbody><tr><td>强缓存</td><td>—</td><td>Expires（1.0）、Cache-Control: max-age/s-maxage（1.1）</td></tr><tr><td>协商-时间</td><td>If-Modified-Since</td><td>Last-Modified</td></tr><tr><td>协商-标识</td><td>If-None-Match</td><td>ETag</td></tr><tr><td>条件-改后取</td><td>If-Match</td><td>—</td></tr><tr><td>禁止缓存</td><td>Cache-Control: no-store（请求/响应均可）</td><td>—</td></tr></tbody></table><ul><li>面试高频：<strong>ETag 比 Last-Modified 更准</strong>（内容变化才变、可解决秒级精度与内容没变但 mtime 变的问题），优先用 ETag。</li></ul><h2 id="跨域-cors" tabindex="-1">跨域 CORS <a class="header-anchor" href="#跨域-cors" aria-label="Permalink to &quot;跨域 CORS&quot;">​</a></h2><h3 id="什么是同源策略与跨域" tabindex="-1">什么是同源策略与跨域 <a class="header-anchor" href="#什么是同源策略与跨域" aria-label="Permalink to &quot;什么是同源策略与跨域&quot;">​</a></h3><ul><li><strong>同源</strong> = 协议 + 域名 + 端口 三者一致；任一不同即为跨域，浏览器默认拦截跨域请求的<strong>响应读取</strong>（请求其实可能发出去了）。</li><li>跨域是浏览器的安全机制，不是服务器的限制；CORS 是服务端&quot;开白名单&quot;放行的标准方案。</li><li>完整方案清单（JSONP/CORS/代理）见<a href="./跨域">跨域</a>。</li></ul><h3 id="简单请求与预检请求" tabindex="-1">简单请求与预检请求 <a class="header-anchor" href="#简单请求与预检请求" aria-label="Permalink to &quot;简单请求与预检请求&quot;">​</a></h3><ul><li><strong>简单请求</strong>：方法为 GET/HEAD/POST 且仅用 CORS 安全头（Accept、Content-Type 为表单三兄弟等）→ 直接发，响应带 <code>Access-Control-Allow-Origin</code> 即放行。</li><li><strong>预检请求（Preflight）</strong>：方法非简单（PUT/DELETE）、或带自定义头（如 <code>Authorization</code>）、或 Content-Type 为 <code>application/json</code> → 浏览器先发 <code>OPTIONS</code> 预检，服务器回 <code>Access-Control-Allow-*</code> 通过后才发真实请求。</li><li>面试题&quot;为什么会有两次请求&quot;：就是预检；用 <code>Access-Control-Max-Age</code> 可缓存预检结果减少次数。</li></ul><h3 id="跨域要带-cookie-怎么办" tabindex="-1">跨域要带 Cookie 怎么办 <a class="header-anchor" href="#跨域要带-cookie-怎么办" aria-label="Permalink to &quot;跨域要带 Cookie 怎么办&quot;">​</a></h3><ul><li>前端：<code>fetch</code> 设 <code>credentials: &#39;include&#39;</code>（XHR 设 <code>withCredentials = true</code>）。</li><li>后端：<code>Access-Control-Allow-Origin</code> <strong>不能是 <code>*</code></strong>，必须是具体源，且响应头 <code>Access-Control-Allow-Credentials: true</code>。</li><li>Cookie 的 <code>SameSite=None; Secure</code> 才能跨站发送，否则会被浏览器拦（Chrome 默认 Lax）。</li></ul><h2 id="连接管理-短连接、keep-alive-与队头阻塞" tabindex="-1">连接管理：短连接、keep-alive 与队头阻塞 <a class="header-anchor" href="#连接管理-短连接、keep-alive-与队头阻塞" aria-label="Permalink to &quot;连接管理：短连接、keep-alive 与队头阻塞&quot;">​</a></h2><h3 id="http-1-0-与-http-1-1-的差异" tabindex="-1">HTTP/1.0 与 HTTP/1.1 的差异 <a class="header-anchor" href="#http-1-0-与-http-1-1-的差异" aria-label="Permalink to &quot;HTTP/1.0 与 HTTP/1.1 的差异&quot;">​</a></h3><ul><li>HTTP/1.0：每次请求新建 TCP 连接、用完即关（<strong>短连接</strong>），且请求里无 Host 头（一台机器只能服务一个站点）。</li><li>HTTP/1.1：默认 <strong>keep-alive 长连接</strong>（复用 TCP）、必须带 <code>Host</code> 头（虚拟主机）、支持 <code>Range</code> 断点续传、管线化（pipelining）等。</li><li>HTTP/1.1 默认长连接，<code>Connection: close</code> 可显式关闭；1.0 要长连则发 <code>Connection: keep-alive</code>。</li></ul><h3 id="长连接是怎么实现的-有什么好处" tabindex="-1">长连接是怎么实现的，有什么好处 <a class="header-anchor" href="#长连接是怎么实现的-有什么好处" aria-label="Permalink to &quot;长连接是怎么实现的，有什么好处&quot;">​</a></h3><ul><li>长连接让多个 HTTP 请求复用同一条 TCP 连接，省去反复三次握手/慢启动的开销 → 减少延迟、降低服务器资源消耗。</li><li>浏览器对同域并发 TCP 连接数有限制（HTTP/1.1 一般 6 条），多出来的请求排队。</li><li>服务端通过超时与最大请求数回收空闲长连接（如 Nginx keepalive_timeout）。</li></ul><h3 id="什么是队头阻塞-hol-blocking" tabindex="-1">什么是队头阻塞（HOL blocking） <a class="header-anchor" href="#什么是队头阻塞-hol-blocking" aria-label="Permalink to &quot;什么是队头阻塞（HOL blocking）&quot;">​</a></h3><ul><li>HTTP/1.1 队头阻塞：同一连接上<strong>前一个请求的响应没返回，后面的响应就得等</strong>（管线化在浏览器基本没启用）。</li><li>缓解手段：浏览器开多条 TCP 连接（并行 6 条）、域名分片（把静态资源放多个子域）。</li><li>注意：HTTP/1.1 的队头阻塞来自&quot;请求-响应的串行&quot;，HTTP/2 解决了它但引入了新的 TCP 层队头阻塞（见下节）。</li></ul><h3 id="短连接与长连接怎么选" tabindex="-1">短连接与长连接怎么选 <a class="header-anchor" href="#短连接与长连接怎么选" aria-label="Permalink to &quot;短连接与长连接怎么选&quot;">​</a></h3><ul><li>短连接：请求极少、低频小请求（省连接管理）；缺点是每次握手开销大。</li><li>长连接：高并发高频请求（同域页面几十个静态资源、API 调用）；缺点是占用连接资源、需处理超时/断线重连。</li><li>名词辨析：HTTP 长连接（keep-alive）是复用连接；TCP 长连接多指心跳保活（WebSocket 等场景）。</li></ul><h2 id="http-2" tabindex="-1">HTTP/2 <a class="header-anchor" href="#http-2" aria-label="Permalink to &quot;HTTP/2&quot;">​</a></h2><h3 id="http-2-解决了什么问题" tabindex="-1">HTTP/2 解决了什么问题 <a class="header-anchor" href="#http-2-解决了什么问题" aria-label="Permalink to &quot;HTTP/2 解决了什么问题&quot;">​</a></h3><ul><li>目标：解决 HTTP/1.1 的<strong>队头阻塞</strong>与<strong>头部冗余</strong>两大痛点，同时保持语义兼容（方法/状态码/头字段不变）。</li><li>核心手段：二进制分帧 + 多路复用 + 头部压缩 + 服务端推送。</li><li>上线前提：HTTPS（主流浏览器要求 HTTP/2 over TLS，ALPN 协商）。</li></ul><h3 id="二进制分帧与多路复用" tabindex="-1">二进制分帧与多路复用 <a class="header-anchor" href="#二进制分帧与多路复用" aria-label="Permalink to &quot;二进制分帧与多路复用&quot;">​</a></h3><ul><li>HTTP/1.x 报文是纯文本、按顺序解析；HTTP/2 把报文拆成一个个 <strong>frame（帧）</strong>，不同请求的帧交错在同一 TCP 连接上传输，接收方按 stream id 重组。</li><li>一个连接上可同时跑多个 <strong>stream（流）</strong>，互不等待 → 真正并行，消除了应用层的队头阻塞。</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">HTTP/1.1：连接串行 [请求A...响应A][请求B...响应B]</span></span>
<span class="line"><span style="color:#e1e4e8;">HTTP/2  ：一个 TCP 连接里 A、B、C 的帧交错传输</span></span>
<span class="line"><span style="color:#e1e4e8;">          ── A1 B1 A2 C1 B2 A3 C2 ── (stream id 区分归属)</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">HTTP/1.1：连接串行 [请求A...响应A][请求B...响应B]</span></span>
<span class="line"><span style="color:#24292e;">HTTP/2  ：一个 TCP 连接里 A、B、C 的帧交错传输</span></span>
<span class="line"><span style="color:#24292e;">          ── A1 B1 A2 C1 B2 A3 C2 ── (stream id 区分归属)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>帧有优先级/依赖设置，可让首屏资源优先到达。</li></ul><h3 id="hpack-头部压缩" tabindex="-1">HPACK 头部压缩 <a class="header-anchor" href="#hpack-头部压缩" aria-label="Permalink to &quot;HPACK 头部压缩&quot;">​</a></h3><ul><li>请求头重复度高（Cookie、User-Agent 每次都一样）。HPACK 用<strong>静态表 + 动态表 + Huffman 编码</strong>把重复头压缩。</li><li>静态表：61 个常见头（如 <code>:method: GET</code>）用 1 字节索引代替。</li><li>动态表：连接内双方各自维护，出现过的头加入表，后续用索引引用。</li><li>效果：头部体积通常减少 80% 以上，尤其对小请求收益巨大。</li></ul><h3 id="server-push-服务端推送" tabindex="-1">Server Push（服务端推送） <a class="header-anchor" href="#server-push-服务端推送" aria-label="Permalink to &quot;Server Push（服务端推送）&quot;">​</a></h3><ul><li>服务器预测客户端会请求的资源（如 HTML 里的 CSS/JS），在收到 HTML 请求后<strong>主动推送</strong>，省去客户端再次请求的往返。</li><li>现实情况：需要服务端明确配置；浏览器支持度反复（Chrome 已默认关闭/移除），实践中<strong>优先级远低于&quot;预加载&quot;与 HTTP/3</strong>，面试了解即可。</li></ul><h3 id="http-2-为什么还有队头阻塞" tabindex="-1">HTTP/2 为什么还有队头阻塞 <a class="header-anchor" href="#http-2-为什么还有队头阻塞" aria-label="Permalink to &quot;HTTP/2 为什么还有队头阻塞&quot;">​</a></h3><ul><li>HTTP/2 消除了<strong>HTTP 层的队头阻塞</strong>，但 HTTP/2 依赖 TCP：TCP 保证有序传输，一个包丢失会触发重传并阻塞后续所有数据，即使它们属于不同 stream。</li><li>这就是 <strong>TCP 层队头阻塞</strong>——丢包率高的弱网下，多路复用优势被抵消。</li><li>根治方案是 HTTP/3 把传输层换成基于 UDP 的 QUIC（每个 stream 独立可靠传输）。</li></ul><h2 id="http-3-quic" tabindex="-1">HTTP/3（QUIC） <a class="header-anchor" href="#http-3-quic" aria-label="Permalink to &quot;HTTP/3（QUIC）&quot;">​</a></h2><h3 id="quic-为什么基于-udp-还可靠" tabindex="-1">QUIC 为什么基于 UDP 还可靠 <a class="header-anchor" href="#quic-为什么基于-udp-还可靠" aria-label="Permalink to &quot;QUIC 为什么基于 UDP 还可靠&quot;">​</a></h3><ul><li>HTTP/3 的传输层是 <strong>QUIC</strong>，跑在 UDP 之上，把&quot;可靠传输、拥塞控制、加密、多路复用&quot;全部在用户态实现。</li><li>QUIC 内部给每个 stream 独立做可靠性与流量控制：一个 stream 丢包<strong>只重传该 stream</strong>，不影响其他 stream → 彻底消除 TCP 层队头阻塞。</li><li>连接建立更快：QUIC 握手合并了传输握手与 TLS 1.3 握手。</li></ul><h3 id="_0-rtt-与连接迁移" tabindex="-1">0-RTT 与连接迁移 <a class="header-anchor" href="#_0-rtt-与连接迁移" aria-label="Permalink to &quot;0-RTT 与连接迁移&quot;">​</a></h3><ul><li><strong>0-RTT</strong>：与服务器通信过的客户端，重连时可携带上次协商的密钥直接发数据，省掉整个握手往返（有重放风险，用于安全要求不高的场景）。</li><li><strong>1-RTT</strong>：首次连接需要一次往返完成握手（QUIC + TLS 1.3）。</li><li><strong>连接迁移</strong>：连接用 <strong>Connection ID</strong> 标识而非四元组（IP+端口），手机切 WiFi/4G 时 IP 变了连接不断，不需要重连。</li><li>面试口径：HTTP/3 = HTTP 语义 + QUIC（UDP + TLS1.3 + 多路复用 + 0-RTT + 连接迁移）。</li></ul><h3 id="http-3-的现状与问题" tabindex="-1">HTTP/3 的现状与问题 <a class="header-anchor" href="#http-3-的现状与问题" aria-label="Permalink to &quot;HTTP/3 的现状与问题&quot;">​</a></h3><ul><li>优势场景：弱网、移动网络、高丢包环境改善明显。</li><li>现实问题：UDP 在部分企业网络/中间设备被限速或封锁；服务端与 CDN 支持仍在普及；CPU 开销高于 TCP。</li><li>演进结论话术：HTTP/1.1（文本、串行）→ HTTP/2（二进制、多路复用，仍受 TCP 队头阻塞）→ HTTP/3（UDP+QUIC，解决传输层队头阻塞）。</li></ul><h2 id="https-http-层视角" tabindex="-1">HTTPS（HTTP 层视角） <a class="header-anchor" href="#https-http-层视角" aria-label="Permalink to &quot;HTTPS（HTTP 层视角）&quot;">​</a></h2><h3 id="http-与-https-的区别" tabindex="-1">HTTP 与 HTTPS 的区别 <a class="header-anchor" href="#http-与-https-的区别" aria-label="Permalink to &quot;HTTP 与 HTTPS 的区别&quot;">​</a></h3><ul><li>HTTPS = HTTP + TLS/SSL：在 HTTP 与 TCP 之间加了一层 TLS，提供<strong>加密、完整性校验、身份认证</strong>。</li><li>默认端口：HTTP 80、HTTPS 443。</li><li>防窃听（明文变密文）、防篡改（MAC 校验）、防冒充（证书验身份）；TLS 记录层的细节在<a href="./../后端/Java/07-计算机网络">计算机网络笔记</a>。</li></ul><h3 id="tls-握手流程-简要版" tabindex="-1">TLS 握手流程（简要版） <a class="header-anchor" href="#tls-握手流程-简要版" aria-label="Permalink to &quot;TLS 握手流程（简要版）&quot;">​</a></h3><ul><li>一次典型握手（TLS 1.2，RSA/ECDHE 类）： <ol><li>ClientHello：客户端发随机数、支持的加密套件列表。</li><li>ServerHello：服务器选定套件、回自己的随机数；下发<strong>证书链</strong>。</li><li>客户端验证证书（链到受信根 CA），用证书公钥完成密钥交换（如 ECDHE 参数或加密预主密钥）。</li><li>双方各自算出<strong>会话密钥</strong>（对称密钥），互相发 Finished 确认。</li><li>之后应用数据用会话密钥对称加密传输。</li></ol></li><li>简化记忆：<strong>非对称/证书完成&quot;身份认证+密钥协商&quot;，对称加密承载&quot;实际数据&quot;</strong>。</li><li>TLS 1.3：握手缩到 1-RTT，去掉弱套件，支持 0-RTT 恢复。</li></ul><h3 id="对称加密-非对称加密怎么配合" tabindex="-1">对称加密 + 非对称加密怎么配合 <a class="header-anchor" href="#对称加密-非对称加密怎么配合" aria-label="Permalink to &quot;对称加密 + 非对称加密怎么配合&quot;">​</a></h3><ul><li>对称加密（AES 等）：快，但密钥怎么安全地给到对方是难题。</li><li>非对称加密（RSA/ECDHE）：公钥加密私钥解密，可安全交换，但慢、密文大。</li><li>配合：用<strong>非对称/密钥交换算法协商出一个临时会话密钥</strong>，之后全程用对称加密传输 → 兼顾安全与性能（混合加密）。</li></ul><h3 id="证书链与-ca-的作用" tabindex="-1">证书链与 CA 的作用 <a class="header-anchor" href="#证书链与-ca-的作用" aria-label="Permalink to &quot;证书链与 CA 的作用&quot;">​</a></h3><ul><li>服务器证书由 <strong>CA（证书颁发机构）</strong> 签发；证书里含域名、公钥、有效期、CA 签名。</li><li>证书链：<code>服务器证书 ← 中间 CA 证书 ← 根 CA 证书</code>，浏览器内置受信根证书库，逐级验证签名直到信任的根。</li><li>校验点：域名匹配（SAN）、有效期、链完整、是否被吊销（OCSP）。</li><li>自签名证书不会被浏览器信任，会报警告——这就是本地 https 调试常见的坑。</li></ul><h3 id="中间人攻击与防范" tabindex="-1">中间人攻击与防范 <a class="header-anchor" href="#中间人攻击与防范" aria-label="Permalink to &quot;中间人攻击与防范&quot;">​</a></h3><ul><li><strong>中间人（MITM）</strong>：攻击者插在客户端与服务器之间，各自伪装成对方，解密/篡改流量。</li><li>HTTPS 防 MITM 的关键是<strong>证书验证</strong>：客户端校验证书不是真的（自签名/域名不符/CA 不受信）时就应拒绝连接。</li><li>防范：不点&quot;继续访问&quot;绕过警告；企业/抓包工具装的根证书本质上就是&quot;被信任的中间人&quot;；服务端开启 HSTS 强制 HTTPS、证书固定（pinning）用于高安全场景。</li><li>与<a href="./前端安全">前端安全</a>的关系：XSS/CSRF 是应用层攻击，HTTPS 管的是传输链路安全，两者互补。</li></ul><h2 id="高频面试-q-a-串讲-15-题" tabindex="-1">高频面试 Q&amp;A 串讲（15 题） <a class="header-anchor" href="#高频面试-q-a-串讲-15-题" aria-label="Permalink to &quot;高频面试 Q&amp;A 串讲（15 题）&quot;">​</a></h2><h3 id="q1-输入-url-到页面展示-http-部分发生了什么" tabindex="-1">Q1：输入 URL 到页面展示，HTTP 部分发生了什么 <a class="header-anchor" href="#q1-输入-url-到页面展示-http-部分发生了什么" aria-label="Permalink to &quot;Q1：输入 URL 到页面展示，HTTP 部分发生了什么&quot;">​</a></h3><ul><li>解析 URL → DNS 解析域名拿 IP → 建立 TCP 连接（三次握手）→ HTTPS 则先 TLS 握手 → 发 HTTP 请求（请求行+头+body）→ 服务器返回响应（状态行+头+body）→ 浏览器解析 HTML，期间<strong>并发请求</strong> CSS/JS/图片（走缓存或网络）→ 页面渲染。</li><li>浏览器里看到的往往是<strong>一串请求</strong>而不是一个：主文档 + 静态资源各自是一次 HTTP 事务。</li><li>关联阅读：<a href="./页面加载执行">页面加载执行</a>（渲染侧）、<a href="./../后端/Java/07-计算机网络">计算机网络笔记</a>（TCP/DNS 细节）。</li></ul><h3 id="q2-get-与-post-的完整区别" tabindex="-1">Q2：GET 与 POST 的完整区别 <a class="header-anchor" href="#q2-get-与-post-的完整区别" aria-label="Permalink to &quot;Q2：GET 与 POST 的完整区别&quot;">​</a></h3><ul><li>语义：GET 取资源、POST 提交变更；GET 幂等可缓存、POST 不保证。</li><li>载体：GET 参数在 URL（有长度限制、会进日志/历史记录），POST 参数在 body（容量大）。</li><li>安全：两者明文等价，都不安全；敏感数据必须靠 HTTPS，而不是靠 POST。</li><li>缓存与回退：GET 可被浏览器缓存、可刷新重放；POST 默认不缓存，重复提交要防重。</li><li>详见上文&quot;HTTP 请求方法&quot;一节。</li></ul><h3 id="q3-304-是怎么产生的-与强缓存什么关系" tabindex="-1">Q3：304 是怎么产生的，与强缓存什么关系 <a class="header-anchor" href="#q3-304-是怎么产生的-与强缓存什么关系" aria-label="Permalink to &quot;Q3：304 是怎么产生的，与强缓存什么关系&quot;">​</a></h3><ul><li>流程：资源上次响应带 <code>ETag</code>/<code>Last-Modified</code> 且缓存策略允许 → 本次请求带 <code>If-None-Match</code>/<code>If-Modified-Since</code> → 服务器比对未变化 → 返回 <strong>304 + 空 body</strong> → 浏览器用本地缓存。</li><li>关系：强缓存命中（<code>Cache-Control: max-age</code> 内）根本不发请求；<strong>发请求还返回 304</strong> 说明强缓存已过期、走的是协商缓存。</li><li>刷 F5 与 Ctrl+F5 对两者的影响见<a href="./浏览器缓存">浏览器缓存</a>。</li></ul><h3 id="q4-长连接与短连接的区别和应用" tabindex="-1">Q4：长连接与短连接的区别和应用 <a class="header-anchor" href="#q4-长连接与短连接的区别和应用" aria-label="Permalink to &quot;Q4：长连接与短连接的区别和应用&quot;">​</a></h3><ul><li>短连接：一来一回就关 TCP（HTTP/1.0 默认），简单但握手开销大。</li><li>长连接：复用连接处理多个请求（HTTP/1.1 默认 keep-alive），省握手、可做管线化。</li><li>应用：Web 页面资源密集用长连接；低频接口/需要及时释放资源的场景考虑短连接；服务端要设超时防止连接泄漏。</li></ul><h3 id="q5-http-1-1、http-2、http-3-演进对比" tabindex="-1">Q5：HTTP/1.1、HTTP/2、HTTP/3 演进对比 <a class="header-anchor" href="#q5-http-1-1、http-2、http-3-演进对比" aria-label="Permalink to &quot;Q5：HTTP/1.1、HTTP/2、HTTP/3 演进对比&quot;">​</a></h3><table><thead><tr><th>维度</th><th>HTTP/1.1</th><th>HTTP/2</th><th>HTTP/3</th></tr></thead><tbody><tr><td>传输</td><td>文本</td><td>二进制分帧</td><td>二进制（QUIC）</td></tr><tr><td>底层</td><td>TCP</td><td>TCP</td><td>UDP + QUIC</td></tr><tr><td>连接复用</td><td>串行（多 TCP）</td><td>多路复用单连接</td><td>多路复用单连接</td></tr><tr><td>队头阻塞</td><td>有（应用层）</td><td>传输层仍有（TCP）</td><td>基本消除</td></tr><tr><td>头部压缩</td><td>无</td><td>HPACK</td><td>QPACK</td></tr><tr><td>握手</td><td>多次往返</td><td>TLS 一般 1-2 RTT</td><td>0/1-RTT</td></tr><tr><td>其他</td><td>Host 头/Range</td><td>Server Push</td><td>连接迁移</td></tr></tbody></table><h3 id="q6-http-2-多路复用为什么还有队头阻塞" tabindex="-1">Q6：HTTP/2 多路复用为什么还有队头阻塞 <a class="header-anchor" href="#q6-http-2-多路复用为什么还有队头阻塞" aria-label="Permalink to &quot;Q6：HTTP/2 多路复用为什么还有队头阻塞&quot;">​</a></h3><ul><li>多路复用解决的是&quot;请求在应用层排队&quot;；但所有 stream 共享一条 TCP，TCP 必须按序交付。</li><li>一旦底层丢包，TCP 重传期间后续数据全部卡住 → 不同 stream 互相拖累。</li><li>一句话：<strong>队头阻塞从 HTTP 层转移到了 TCP 层</strong>，丢包率越高影响越大。</li></ul><h3 id="q7-断点续传-分块上传怎么实现" tabindex="-1">Q7：断点续传 / 分块上传怎么实现 <a class="header-anchor" href="#q7-断点续传-分块上传怎么实现" aria-label="Permalink to &quot;Q7：断点续传 / 分块上传怎么实现&quot;">​</a></h3><ul><li>下载续传：请求头 <code>Range: bytes=1024-</code>（从 1024 字节开始），服务器支持则返回 <strong>206 Partial Content + <code>Content-Range: bytes 1024-2047/2048</code></strong>，不支持就回 200 全量。</li><li>条件续传：带 <code>If-Range: &lt;etag&gt;</code>，资源没变才给 206，变了给 200 重新下。</li><li>上传分块：客户端把文件切片逐个上传，服务端记录每片偏移，最后合并；或用 multipart 多段；断点续传思路相同（记录已传偏移）。</li><li>应用：下载工具断点续传、大文件秒传（先传 hash 判重）。</li></ul><h3 id="q8-sse-与-websocket-的区别" tabindex="-1">Q8：SSE 与 WebSocket 的区别 <a class="header-anchor" href="#q8-sse-与-websocket-的区别" aria-label="Permalink to &quot;Q8：SSE 与 WebSocket 的区别&quot;">​</a></h3><table><thead><tr><th>维度</th><th>SSE（Server-Sent Events）</th><th>WebSocket</th></tr></thead><tbody><tr><td>方向</td><td>服务器 → 客户端单向</td><td>全双工</td></tr><tr><td>协议</td><td>普通 HTTP（<code>text/event-stream</code>）</td><td>独立协议（HTTP Upgrade 101 握手后）</td></tr><tr><td>自动重连</td><td>自带（EventSource 自动重连+断点续传 id）</td><td>需自己实现</td></tr><tr><td>消息格式</td><td>文本</td><td>文本/二进制</td></tr><tr><td>适用</td><td>服务端推送：通知、股票、日志流</td><td>聊天、游戏、双向实时交互</td></tr></tbody></table><ul><li>一句话：只要&quot;服务器单向下发&quot;（通知、feed），优先 SSE——基于 HTTP 简单、能过代理、自动重连；需要双向实时通信才上 WebSocket。</li></ul><h3 id="q9-为什么需要-content-type-与-accept-什么时候会有两次请求" tabindex="-1">Q9：为什么需要 Content-Type 与 Accept，什么时候会有两次请求 <a class="header-anchor" href="#q9-为什么需要-content-type-与-accept-什么时候会有两次请求" aria-label="Permalink to &quot;Q9：为什么需要 Content-Type 与 Accept，什么时候会有两次请求&quot;">​</a></h3><ul><li>Accept 声明&quot;我能接受什么&quot;，Content-Type 声明&quot;这个 body 是什么&quot;——两者配合完成内容协商（格式、压缩、语言）。</li><li>两次请求 = CORS <strong>预检</strong>：非简单请求（自定义头、JSON、PUT/DELETE）先发 OPTIONS，通过后再发真实请求；可用 <code>Access-Control-Max-Age</code> 缓存预检。</li><li>详见上文 CORS 节与<a href="./跨域">跨域</a>。</li></ul><h3 id="q10-http-无状态-登录态怎么保持" tabindex="-1">Q10：HTTP 无状态，登录态怎么保持 <a class="header-anchor" href="#q10-http-无状态-登录态怎么保持" aria-label="Permalink to &quot;Q10：HTTP 无状态，登录态怎么保持&quot;">​</a></h3><ul><li>方案一 Session+Cookie：登录后服务端记 session，SessionID 下到 Cookie，请求自动携带。</li><li>方案二 Token（JWT）：登录后发签名 token，客户端存起来（localStorage/内存），请求头带 <code>Authorization: Bearer xxx</code>。</li><li>方案三（简单场景）签名 Cookie 直接存用户标识。</li><li>横向扩展：Session 需集中存储（Redis），Token 天然适合分布式；见上文 Cookie 与 Session 节。</li></ul><h3 id="q11-代理转发后怎么拿真实-ip" tabindex="-1">Q11：代理转发后怎么拿真实 IP <a class="header-anchor" href="#q11-代理转发后怎么拿真实-ip" aria-label="Permalink to &quot;Q11：代理转发后怎么拿真实 IP&quot;">​</a></h3><ul><li>请求经过 Nginx/CDN 等反向代理，服务端看到的源 IP 是代理的。</li><li>代理把真实 IP 追加到 <code>X-Forwarded-For</code>（每经过一跳追加一个）或 <code>X-Real-IP</code>（Nginx 常见）。</li><li>注意：这些头<strong>客户端可伪造</strong>，只有可信代理设置/覆盖时才可信；取&quot;最左的第一个不可信段&quot;要结合代理链配置判断。</li></ul><h3 id="q12-chunked-分块传输是干什么的" tabindex="-1">Q12：chunked 分块传输是干什么的 <a class="header-anchor" href="#q12-chunked-分块传输是干什么的" aria-label="Permalink to &quot;Q12：chunked 分块传输是干什么的&quot;">​</a></h3><ul><li><code>Transfer-Encoding: chunked</code>：响应体长度未知时（如流式输出、动态生成大文件），边生成边按&quot;长度+块数据&quot;发送，最后发一个 0 长度块结束。</li><li>与 <code>Content-Length</code> 互斥：有 chunked 就不写 Content-Length。</li><li>应用：SSE、大文件流式下载、服务端渲染流式输出；面试答&quot;动态内容、长度未知、流式传输&quot;即命中。</li></ul><h3 id="q13-options-预检在哪些场景出现" tabindex="-1">Q13：OPTIONS 预检在哪些场景出现 <a class="header-anchor" href="#q13-options-预检在哪些场景出现" aria-label="Permalink to &quot;Q13：OPTIONS 预检在哪些场景出现&quot;">​</a></h3><ul><li>方法不是 GET/HEAD/POST；或 POST 的 Content-Type 不是表单三类；或带了自定义请求头（Authorization、X-Token）；或请求带非简单头的 cookie 凭证场景。</li><li>出现两次请求先别慌：预检 200 只是&quot;放行&quot;，看真实请求是否成功。</li><li>优化：合并请求头（少自定义头）、服务端配 <code>Access-Control-Max-Age</code> 缓存预检。</li></ul><h3 id="q14-cdn-缓存与浏览器缓存怎么配合" tabindex="-1">Q14：CDN 缓存与浏览器缓存怎么配合 <a class="header-anchor" href="#q14-cdn-缓存与浏览器缓存怎么配合" aria-label="Permalink to &quot;Q14：CDN 缓存与浏览器缓存怎么配合&quot;">​</a></h3><ul><li>CDN 是&quot;中间层缓存&quot;：用户请求先打到 CDN 边缘节点，命中则直接返回，未命中才回源站。</li><li>控制头分两层：<code>Cache-Control: max-age</code> 管浏览器/本地；<code>s-maxage</code>/<code>public</code> 管 CDN/共享缓存；<code>no-cache</code> 让 CDN 每次回源校验。</li><li>版本号/文件名 hash（指纹）更新时，浏览器与 CDN 缓存一起失效 → 前端构建的静态资源更新策略。</li><li>详见<a href="./浏览器缓存">浏览器缓存</a>的缓存场景与静态资源指纹。</li></ul><h3 id="q15-https-全流程一句话串讲" tabindex="-1">Q15：HTTPS 全流程一句话串讲 <a class="header-anchor" href="#q15-https-全流程一句话串讲" aria-label="Permalink to &quot;Q15：HTTPS 全流程一句话串讲&quot;">​</a></h3><ul><li>客户端连服务器 → TCP 三次握手 → TLS 握手（校验证书链确认身份 + 协商会话密钥）→ 之后 HTTP 报文用会话密钥对称加密传输 → 结束用四次挥手断开。</li><li>安全三件套：加密（防窃听）、完整性（防篡改）、认证（防冒充）。</li><li>密钥交换与握手细节、证书校验、中间人的关系见上文 HTTPS 一节与<a href="./../后端/Java/07-计算机网络">计算机网络笔记</a>。</li></ul>`,148)]))}const p=e(i,[["render",n]]);export{T as __pageData,p as default};
